events.syntax:
if row.matches_owner(source.incarnation) and row.has_started:
    native_id = row.native_id
    if native_id in started:
        raise ValueError('Continued private native start is ambiguous')
    started[native_id] = row

if native_id in recorded:
    proof = recorded[native_id]
    if proof.session_entry_id != entry.id or proof != NativeContextProof.read_evidence(session, native_id, request_generation=proof.request_generation, evidence=evidence):
        raise ValueError('Continued private user differs from live-recorded context')
elif native_id not in retained:
    raise ValueError('Continued private user has no verified retained context')

if queued.get(item.input_id) is item:
    queued.pop(item.input_id)
    await self.emit_queue_state(session_id)

if isinstance(entry, MessageEntry):
    message = raw['message']
    if message.get('inputId') is not None and (not entry.message.user):
        raise ValueError('Tracked native input must belong to a user')
    if entry.message.user and isinstance(entry.message.content, tuple):
        content = tuple((part.preserve_evidence(raw_part) for part, raw_part in zip(entry.message.content, message['content'], strict=True)))
        entry = replace(entry, message=replace(entry.message, content=content))

if user is not None and user.input_id is not None and (db is not None):
    originals = cls.for_native_user(db, reader, user)
    if entry.final_reply:
        for original in originals:
            publications = original.published_replies(db, user, owner_lookup)

if not binding.bind(current=current, keys=source.keys, admission=self.admission, turn=self.turn, native_id=native_id, text=sent_text, already_bound=already_bound):
    yield self._refusal(UnboundOrdinaryInputRule(), defer)
    return

if len(origins) != len(group) or not sent_text.endswith(source):
    report['skipped'] += 1
    continue

if (session.require_input_id or input_id in self.accepted) and text == queued_text and (not session.require_input_id or native_id == expected_native_id):
    if not session.notify_input_started(input_id, expected_native_id, queued_text):
        return (False, None)
    self.accepted.discard(input_id)
    self.pending.pop(index)
    self.started = True
    return (True, input_id)
